  (1, 1, 8, '{"words":["This","ball","are","red."],"wrongIndex":2,"fixes":["am","is","be"],"answer":1}'),
  (1, 1, 9, '{"words":["My","dad","am","tall."],"wrongIndex":2,"fixes":["is","are","be"],"answer":0,"picture":"man"}'),
  (1, 1, 10, '{"prompt":"Build the sentence.","tiles":["The","sun","is","hot."],"distractors":["are"],"picture":"sun"}'),
  (1, 1, 11, '{"prompt":"Build the sentence.","tiles":["My","books","are","on","the","desk."],"distractors":["is"],"picture":"books"}'),
  (1, 1, 12, '{"prompt":"Sort the words.","groups":["am","is","are"],"items":[{"text":"I","group":0},{"text":"the cat","group":1},{"text":"we","group":2},{"text":"Ben","group":1},{"text":"you","group":2}]}'),
