  (1, 2, 6, '{"before":"Mia is my sister.","after":"is five.","choices":["She","They","We"],"answer":0}'),
  (1, 2, 7, '{"words":["Mom","and","I","is","in","the","kitchen."],"wrongIndex":3,"fixes":["am","are","be"],"answer":1,"picture":"cooking"}'),
  (1, 2, 8, '{"words":["Three","girls","is","at","school."],"wrongIndex":2,"fixes":["are","am","be"],"answer":0,"picture":"school"}'),
  (1, 2, 9, '{"words":["We","is","good","friends."],"wrongIndex":1,"fixes":["am","are","be"],"answer":1}'),
