  (1, 2, 12, '{"prompt":"Sort the words.","groups":["is","are"],"items":[{"text":"he","group":0},{"text":"they","group":1},{"text":"Mina","group":0},{"text":"my mom and dad","group":1},{"text":"the dogs","group":1},{"text":"it","group":0}]}'),
  (1, 2, 13, null),
  (1, 2, 14, null),
  (1, 2, 15, null),
  (1, 3, 1, '{"prompt":"Pick the right sentence.","choices":["the cat is soft.","The cat is soft","The cat is soft."],"answer":2,"picture":"cat"}'),
  (1, 3, 2, '{"prompt":"Pick the right sentence.","choices":["mina is my friend.","Mina is my friend.","Mina is my Friend."],"answer":1}'),
  (1, 3, 3, '{"prompt":"Pick the right sentences.","choices":["I have a dog. it is brown.","I have a dog. It is brown.","I have a dog it is brown."],"answer":1,"picture":"dog"}'),
