  (1, 3, 10, '{"prompt":"Build the sentence.","tiles":["Sam","has","a","red","ball."],"distractors":["sam"]}'),
  (1, 3, 11, '{"prompt":"Build the sentence.","tiles":["The","milk","is","cold."],"distractors":["the"],"picture":"glass-of-milk"}'),
  (1, 3, 12, '{"prompt":"Is the name written the right way?","groups":["Right","Wrong"],"items":[{"text":"Mina","group":0},{"text":"leo","group":1},{"text":"Tom","group":0},{"text":"sam","group":1},{"text":"Ben","group":0},{"text":"mia","group":1}]}'),
  (1, 3, 13, null),
