  (1, 5, 1, '{"prompt":"Pick the right sentence.","choices":["I is have a cat.","I have a cat.","I am have a cat."],"answer":1,"picture":"cat"}'),
  (1, 5, 2, '{"prompt":"Pick the right sentences.","choices":["I like apples. they are sweet.","I like apples they are sweet.","I like apples. They are sweet."],"answer":2,"picture":"red-apple"}'),
