  (1, 5, 6, '{"before":"","after":"and Leo are friends.","choices":["mia","Mia","mia."],"answer":1}'),
  (1, 5, 7, '{"words":["They","is","my","dogs."],"wrongIndex":1,"fixes":["are","am","be"],"answer":0,"picture":"dog"}'),
  (1, 5, 8, '{"words":["Mia","is","watch","a","movie."],"wrongIndex":2,"fixes":["watches","watching","watched"],"answer":1,"picture":"popcorn"}'),
  (1, 5, 9, '{"words":["I","play","with","ben."],"wrongIndex":3,"fixes":["Ben.","Ben","ben,"],"answer":0}'),
  (1, 5, 10, '{"prompt":"Build the sentence.","tiles":["My","dad","is","washing","the","car."],"distractors":["wash"],"picture":"automobile"}'),
  (1, 5, 11, '{"prompt":"Build the sentence.","tiles":["Mina","is","at","the","beach."],"distractors":["mina","are"],"picture":"beach-with-umbrella"}'),
  (1, 5, 12, '{"prompt":"Sort the words.","groups":["am","is","are"],"items":[{"text":"I","group":0},{"text":"my shoes","group":2},{"text":"Leo","group":1},{"text":"Mom and I","group":2},{"text":"the bird","group":1}]}'),
