-- ============================ PART 2: APPLY ================================
-- Only run this after you checked the rows from PART 1.
-- It runs as one all-or-nothing step: either every change happens, or none.

begin;

-- Test week · Grade 1
do $$ begin if not exists (select 1 from wp_classes where grade = 1) then
  raise exception 'No class for grade 1: import the roster first'; end if; end $$;
insert into wp_plans (title, kind) values ('Test week · Grade 1', 'test') on conflict (title) do update set kind = excluded.kind;
insert into wp_plan_assignments (plan_id, class_id)
  select (select id from wp_plans where title = 'Test week · Grade 1'), (select id from wp_classes where grade = 1 order by name, id limit 1) where not exists (select 1 from wp_plan_assignments where plan_id = (select id from wp_plans where title = 'Test week · Grade 1') and class_id = (select id from wp_classes where grade = 1 order by name, id limit 1));
insert into wp_weeks (plan_id, position, skill, opens_on) values ((select id from wp_plans where title = 'Test week · Grade 1'), 1, 'am / is / are and -ing', '2026-11-26')
  on conflict (plan_id, position) do nothing;
insert into wp_lessons (week_id, position, title) values ((select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 1') and position = 1), 1, 'Am, Is, Are')
  on conflict (week_id, position) do nothing;
update wp_questions set type = 'pick_one', payload = '{"prompt":"One of these is right. Tap it.","choices":["I am happy.","I is happy.","I are happy."],"answer":0}'::jsonb, skill = 'be', updated_at = now()
  where lesson_id = (select id from wp_lessons where week_id = (select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 1') and position = 1) and position = 1) and position = 1 and deleted_at is null
  and (type <> 'pick_one' or payload <> '{"prompt":"One of these is right. Tap it.","choices":["I am happy.","I is happy.","I are happy."],"answer":0}'::jsonb or skill is distinct from 'be');
insert into wp_questions (lesson_id, position, type, payload, skill) select (select id from wp_lessons where week_id = (select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 1') and position = 1) and position = 1), 1, 'pick_one', '{"prompt":"One of these is right. Tap it.","choices":["I am happy.","I is happy.","I are happy."],"answer":0}'::jsonb, 'be'
  where not exists (select 1 from wp_questions where lesson_id = (select id from wp_lessons where week_id = (select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 1') and position = 1) and position = 1) and position = 1);
